code.cpp:
class Solution {
public:
    int maximumBags(vector<int>& capacity, vector<int>& rocks, int additionalRocks) {
        int n = capacity.size();
        for (int i = 0; i < n; i++) {
            capacity[i] -= rocks[i];
        }
        sort(capacity.begin(), capacity.end());
        int count = 0;
        long long remaining = additionalRocks;
        for (int i = 0; i < n; i++) {
            if (remaining >= capacity[i]) {
                remaining -= capacity[i];
                count++;
            } else {
                break;
            }
        }
        return count;
    }
};
